/* eslint-disable @typescript-eslint/no-explicit-any */
import axios from "axios";
import { useState } from "react";

const api = axios.create({
    baseURL: "http://localhost:8002/api/auth",
    headers: {
        "Content-Type": "application/json"
    }
})

export const useAuth = () => {
    const [error , setError] = useState(null)
    const [loading , setLoading] = useState(false);
    const [user, setUser ] = useState("")

 const verifyOtp = async (data: { otp: string }) => {
    setLoading(true)
    try {
        const response = await api.post("/verifyOtp", data)
        console.log(response.data)
        setUser((response.data as any).user)
        return response.data;
    } catch (error) {
        setError((error as any).response?.data?.user || "Something went wrong")
    } finally {
        setLoading(false)
    }
 }
 return { error, loading, user, verifyOtp };
}
